t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
V=np.var(y)
def mk(form):
    def f(p):
        if form==1:
            g=p[0]*(1-np.exp(-p[1]*t*t))*np.exp(-p[2]*t)+p[3]*t*np.exp(-p[4]*t)
        elif form==2:
            g=p[0]*np.exp(-p[1]*t)+p[2]*t*np.exp(-p[3]*t)+p[4]*np.exp(-p[5]*t*t)
        elif form==3:
            g=p[0]*t**p[1]*np.exp(-p[2]*t)+p[3]*np.exp(-p[4]*t)
        return g - p[-2]*t**2*A**p[-1]
    return f
